import re,json,os
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    G[k]=[[int(x) for x in r] for r in rows]
I=G['Demo pair 1 input']; O=G['Demo pair 1 output']
for r in I: print(r)
print('---')
for r in O: print(r)
print(len(O),len(O[0]))

import numpy as np
I=np.array(I); O=np.array(O)
trans={'id':I,'lr':I[:,::-1],'ud':I[::-1,:],'udlr':I[::-1,::-1]}
for bi in range(3):
    for bj in range(3):
        B=O[bi*8:(bi+1)*8, bj*6:(bj+1)*6]
        names=[n for n,T in trans.items() if (B==T).all()]
        print(bi,bj,names)

for bi in range(3):
    for bj in range(2):
        B=O[bi*8:(bi+1)*8, bj*6:(bj+1)*6]
        print(bi,bj,[n for n,T in trans.items() if (B==T).all()])
